import {
    logPersistenceSuccess,
    logPersistenceWarning
} from './logger.js';
// 解析上报配置
function createConfig(config) {
    if (!config.endpoint && !config.transport) {
        return undefined;
    }
    if (!config.projectId) {
        logPersistenceWarning('PROJECT_ID 未配置');
        return undefined;
    }
    return {
        endpoint: config.endpoint,
        transport: config.transport,
    };
}
// 检查接口响应
async function checkResponse(response) {
    if (response.ok) {
        return true;
    }
    const body = await response.text();
    const message = body || response.statusText;
    throw new Error(`Failed to report we0 event: ${message}`);
}
export class HttpReporter {
    config;
    constructor(config) {
        this.config = createConfig(config);
    }
    isEnabled() {
        return Boolean(this.config);
    }
    async write(event) {
        if (!this.config) {
            return;
        }
        if (this.config.transport) {
            await this.config.transport(event);
            logPersistenceSuccess('custom transport', event);
            return;
        }
        if (!this.config.endpoint) {
            return;
        }
        const response = await fetch(this.config.endpoint, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            keepalive: true,
            body: JSON.stringify(event),
        });
        if (await checkResponse(response)) {
            logPersistenceSuccess(this.config.endpoint, event);
        }
    }
}